function popularityCache(capacity, operations) {
  const entries = new Map(), results = [];
  let tick = 0;
  for (const op of operations) {
    tick++;
    if (op[0] === 'get') {
      const e = entries.get(op[1]);
      if (!e) { results.push(-1); continue; }
      e.uses++; e.last = tick; results.push(e.value);
    } else {
      const e = entries.get(op[1]);
      if (e) { e.value = op[2]; e.uses++; e.last = tick; continue; }
      if (entries.size === capacity) {
        let victim = null, best = null;
        for (const [k, v] of entries) if (!best || v.uses < best.uses || (v.uses === best.uses && v.last < best.last)) { best = v; victim = k; }
        entries.delete(victim);
      }
      entries.set(op[1], { value: op[2], uses: 1, last: tick });
    }
  }
  return results;
}

class PopularityCache {
  constructor(capacity) {
    this.capacity = capacity;
    this.values = new Map();
    this.freq = new Map();
    this.buckets = new Map();
    this.minFreq = 0;
  }
  touch(key) {
    const f = this.freq.get(key);
    const bucket = this.buckets.get(f);
    bucket.delete(key);
    if (bucket.size === 0) { this.buckets.delete(f); if (this.minFreq === f) this.minFreq = f + 1; }
    this.freq.set(key, f + 1);
    if (!this.buckets.has(f + 1)) this.buckets.set(f + 1, new Set());
    this.buckets.get(f + 1).add(key);
  }
  get(key) {
    if (!this.values.has(key)) return -1;
    this.touch(key);
    return this.values.get(key);
  }
  put(key, value) {
    if (this.values.has(key)) { this.values.set(key, value); this.touch(key); return; }
    if (this.values.size === this.capacity) {
      const bucket = this.buckets.get(this.minFreq);
      const victim = bucket.values().next().value;
      bucket.delete(victim);
      if (bucket.size === 0) this.buckets.delete(this.minFreq);
      this.values.delete(victim);
      this.freq.delete(victim);
    }
    this.values.set(key, value);
    this.freq.set(key, 1);
    if (!this.buckets.has(1)) this.buckets.set(1, new Set());
    this.buckets.get(1).add(key);
    this.minFreq = 1;
  }
}

function popularityCache(capacity, operations) {
  const cache = new PopularityCache(capacity), results = [];
  for (const op of operations) {
    if (op[0] === 'get') results.push(cache.get(op[1]));
    else cache.put(op[1], op[2]);
  }
  return results;
}
